import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import toast from 'react-hot-toast'

/**
 * DosageCalculator Component
 * Calculates appropriate drug dosages based on patient characteristics
 */
function DosageCalculator({ patient, onClose }) {
    const [selectedDrug, setSelectedDrug] = useState('')
    const [result, setResult] = useState(null)
    const [loading, setLoading] = useState(false)

    // Common diabetes drugs with dosing guidelines based on eGFR
    const dosageGuidelines = {
        metformin: {
            name: 'Metformin',
            class: 'Biguanide',
            standardDose: '500-2000 mg/day',
            adjustments: [
                { egfrMin: 60, egfrMax: Infinity, dose: '500-2000 mg/day', note: 'Full dose approved' },
                { egfrMin: 45, egfrMax: 60, dose: '500-1000 mg/day', note: 'Reduce dose, monitor renal function' },
                { egfrMin: 30, egfrMax: 45, dose: 'Max 500 mg/day', note: 'Use with caution, increased monitoring' },
                { egfrMin: 0, egfrMax: 30, dose: 'CONTRAINDICATED', note: 'Do NOT use - risk of lactic acidosis' },
            ]
        },
        glipizide: {
            name: 'Glipizide',
            class: 'Sulfonylurea',
            standardDose: '2.5-20 mg/day',
            adjustments: [
                { egfrMin: 30, egfrMax: Infinity, dose: '2.5-20 mg/day', note: 'Start low, titrate carefully' },
                { egfrMin: 15, egfrMax: 30, dose: 'Max 2.5 mg/day', note: 'Increased hypoglycemia risk' },
                { egfrMin: 0, egfrMax: 15, dose: 'Avoid', note: 'Increased risk of severe hypoglycemia' },
            ]
        },
        glyburide: {
            name: 'Glyburide',
            class: 'Sulfonylurea',
            standardDose: '1.25-10 mg/day',
            adjustments: [
                { egfrMin: 60, egfrMax: Infinity, dose: '1.25-10 mg/day', note: 'Standard dosing' },
                { egfrMin: 0, egfrMax: 60, dose: 'AVOID', note: 'Active metabolites accumulate, use glipizide instead' },
            ]
        },
        sitagliptin: {
            name: 'Sitagliptin (Januvia)',
            class: 'DPP-4 Inhibitor',
            standardDose: '100 mg once daily',
            adjustments: [
                { egfrMin: 45, egfrMax: Infinity, dose: '100 mg once daily', note: 'Standard dose' },
                { egfrMin: 30, egfrMax: 45, dose: '50 mg once daily', note: 'Reduce dose by 50%' },
                { egfrMin: 0, egfrMax: 30, dose: '25 mg once daily', note: 'Reduce dose by 75%' },
            ]
        },
        empagliflozin: {
            name: 'Empagliflozin (Jardiance)',
            class: 'SGLT2 Inhibitor',
            standardDose: '10-25 mg once daily',
            adjustments: [
                { egfrMin: 45, egfrMax: Infinity, dose: '10-25 mg once daily', note: 'Full efficacy for glycemic control' },
                { egfrMin: 30, egfrMax: 45, dose: '10 mg once daily', note: 'Reduced glycemic efficacy, CV/renal benefits preserved' },
                { egfrMin: 20, egfrMax: 30, dose: '10 mg once daily', note: 'For cardiorenal protection only' },
                { egfrMin: 0, egfrMax: 20, dose: 'Avoid initiating', note: 'May continue if already on therapy' },
            ]
        },
        lisinopril: {
            name: 'Lisinopril',
            class: 'ACE Inhibitor',
            standardDose: '2.5-40 mg/day',
            adjustments: [
                { egfrMin: 30, egfrMax: Infinity, dose: '2.5-40 mg/day', note: 'Monitor potassium and creatinine' },
                { egfrMin: 10, egfrMax: 30, dose: 'Max 20 mg/day', note: 'Start low, titrate slowly' },
                { egfrMin: 0, egfrMax: 10, dose: 'Max 5 mg/day', note: 'Use with extreme caution, close monitoring' },
            ]
        },
        amlodipine: {
            name: 'Amlodipine',
            class: 'Calcium Channel Blocker',
            standardDose: '2.5-10 mg/day',
            adjustments: [
                { egfrMin: 0, egfrMax: Infinity, dose: '2.5-10 mg/day', note: 'No renal adjustment needed' },
            ]
        },
        atorvastatin: {
            name: 'Atorvastatin (Lipitor)',
            class: 'Statin',
            standardDose: '10-80 mg/day',
            adjustments: [
                { egfrMin: 0, egfrMax: Infinity, dose: '10-80 mg/day', note: 'No renal adjustment, beneficial for CV protection' },
            ]
        },
    }

    const calculateDosage = () => {
        if (!selectedDrug) {
            toast.error('Please select a drug')
            return
        }

        const drug = dosageGuidelines[selectedDrug]
        const patientEgfr = patient?.egfr || 90 // Default to normal if not specified
        const patientAge = patient?.age || 50

        // Find appropriate adjustment
        const adjustment = drug.adjustments.find(
            adj => patientEgfr >= adj.egfrMin && patientEgfr < adj.egfrMax
        ) || drug.adjustments[drug.adjustments.length - 1]

        // Determine risk level
        let riskLevel = 'safe'
        if (adjustment.dose.includes('CONTRAINDICATED') || adjustment.dose.includes('Avoid')) {
            riskLevel = 'contraindicated'
        } else if (adjustment.dose.includes('Max') || adjustment.note.includes('caution')) {
            riskLevel = 'caution'
        }

        // Age-based considerations
        let ageWarning = null
        if (patientAge >= 65) {
            ageWarning = 'Consider starting at lower dose in elderly patients and titrating slowly.'
        }

        setResult({
            drug: drug.name,
            drugClass: drug.class,
            standardDose: drug.standardDose,
            recommendedDose: adjustment.dose,
            note: adjustment.note,
            riskLevel,
            patientEgfr,
            patientAge,
            ageWarning,
        })
    }

    const riskColors = {
        safe: { bg: 'bg-emerald-500/20', text: 'text-emerald-400', border: 'border-emerald-500/30' },
        caution: { bg: 'bg-amber-500/20', text: 'text-amber-400', border: 'border-amber-500/30' },
        contraindicated: { bg: 'bg-red-500/20', text: 'text-red-400', border: 'border-red-500/30' },
    }

    return (
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4"
            onClick={(e) => e.target === e.currentTarget && onClose()}
        >
            <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.9, opacity: 0 }}
                className="bg-slate-900 border border-slate-700 rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-auto shadow-2xl"
            >
                {/* Header */}
                <div className="p-4 border-b border-slate-700 flex items-center justify-between">
                    <div>
                        <h2 className="text-xl font-bold text-white flex items-center gap-2">
                            <span className="text-2xl">­ƒÆè</span>
                            Dosage Calculator
                        </h2>
                        <p className="text-sm text-slate-400">
                            eGFR-based dosing adjustments for {patient?.name || 'patient'}
                        </p>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors"
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                {/* Patient Info */}
                <div className="p-4 bg-slate-800/50 border-b border-slate-700">
                    <div className="flex flex-wrap gap-4 text-sm">
                        <div>
                            <span className="text-slate-400">eGFR: </span>
                            <span className={`font-bold ${(patient?.egfr || 90) >= 60 ? 'text-emerald-400' :
                                    (patient?.egfr || 90) >= 30 ? 'text-amber-400' : 'text-red-400'
                                }`}>
                                {patient?.egfr || 'Not specified'} mL/min/1.73m┬▓
                            </span>
                        </div>
                        <div>
                            <span className="text-slate-400">Age: </span>
                            <span className="text-white font-medium">{patient?.age || 'Not specified'} years</span>
                        </div>
                        <div>
                            <span className="text-slate-400">Diabetes: </span>
                            <span className="text-white font-medium">
                                {(patient?.diabetes_type || 'type_2').replace('_', ' ').toUpperCase()}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Drug Selection */}
                <div className="p-4">
                    <label className="block text-sm font-medium text-slate-300 mb-2">
                        Select Medication
                    </label>
                    <select
                        value={selectedDrug}
                        onChange={(e) => {
                            setSelectedDrug(e.target.value)
                            setResult(null)
                        }}
                        className="w-full px-4 py-3 bg-slate-800 border border-slate-600 rounded-xl text-white focus:border-medical-500 focus:outline-none"
                    >
                        <option value="">-- Select a drug --</option>
                        {Object.entries(dosageGuidelines).map(([key, drug]) => (
                            <option key={key} value={key}>
                                {drug.name} ({drug.class})
                            </option>
                        ))}
                    </select>

                    <button
                        onClick={calculateDosage}
                        disabled={!selectedDrug}
                        className="w-full mt-4 py-3 bg-medical-500 text-white rounded-xl hover:bg-medical-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed font-medium"
                    >
                        Calculate Dose
                    </button>
                </div>

                {/* Result */}
                <AnimatePresence>
                    {result && (
                        <motion.div
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: 'auto' }}
                            exit={{ opacity: 0, height: 0 }}
                            className="p-4 border-t border-slate-700"
                        >
                            <div className={`p-4 rounded-xl border ${riskColors[result.riskLevel].border} ${riskColors[result.riskLevel].bg}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <h3 className="font-bold text-white text-lg">{result.drug}</h3>
                                    <span className={`px-3 py-1 rounded-full text-sm font-medium ${riskColors[result.riskLevel].text} ${riskColors[result.riskLevel].bg} border ${riskColors[result.riskLevel].border}`}>
                                        {result.riskLevel === 'safe' ? 'Ô£ô Safe' :
                                            result.riskLevel === 'caution' ? 'ÔÜá´©Å Caution' : 'Ôøö Contraindicated'}
                                    </span>
                                </div>

                                <div className="space-y-3">
                                    <div className="flex justify-between">
                                        <span className="text-slate-400">Standard Dose:</span>
                                        <span className="text-slate-300">{result.standardDose}</span>
                                    </div>

                                    <div className="flex justify-between">
                                        <span className="text-slate-400">Recommended for this patient:</span>
                                        <span className={`font-bold ${riskColors[result.riskLevel].text}`}>
                                            {result.recommendedDose}
                                        </span>
                                    </div>

                                    <div className="flex justify-between">
                                        <span className="text-slate-400">Patient eGFR:</span>
                                        <span className="text-slate-300">{result.patientEgfr} mL/min/1.73m┬▓</span>
                                    </div>
                                </div>

                                <div className="mt-4 p-3 bg-slate-900/50 rounded-lg">
                                    <p className={`text-sm ${riskColors[result.riskLevel].text}`}>
                                        ­ƒÆí {result.note}
                                    </p>
                                </div>

                                {result.ageWarning && (
                                    <div className="mt-3 p-3 bg-amber-500/10 border border-amber-500/30 rounded-lg">
                                        <p className="text-sm text-amber-400">
                                            ­ƒæ┤ {result.ageWarning}
                                        </p>
                                    </div>
                                )}
                            </div>

                            <p className="text-xs text-slate-500 mt-4 text-center">
                                ÔÜá´©Å This calculator is for reference only. Always consult prescribing information and clinical judgment.
                            </p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </motion.div>
        </motion.div>
    )
}

export default DosageCalculator

import React from 'react'
import { AlertTriangle, RefreshCw, Home } from 'lucide-react'

/**
 * ErrorBoundary - Catches JavaScript errors in child components
 * 
 * This component prevents the entire app from crashing when a component
 * encounters an unhandled error. Instead, it shows a user-friendly error
 * message with recovery options.
 * 
 * @example
 * <ErrorBoundary fallback={<CustomErrorUI />}>
 *   <MyComponent />
 * </ErrorBoundary>
 */
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    }
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render shows the fallback UI
    return { hasError: true, error }
  }

  componentDidCatch(error, errorInfo) {
    // Log the error to console for debugging
    console.error('ErrorBoundary caught an error:', error, errorInfo)

    this.setState({
      error,
      errorInfo,
    })

    // You could also log to an error reporting service here
    // logErrorToService(error, errorInfo)
  }

  handleReload = () => {
    window.location.reload()
  }

  handleGoHome = () => {
    window.location.href = '/'
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null, errorInfo: null })
  }

  render() {
    if (this.state.hasError) {
      // Custom fallback UI if provided
      if (this.props.fallback) {
        return this.props.fallback
      }

      // Default error UI
      return (
        <div
          className="min-h-[400px] flex items-center justify-center p-8"
          role="alert"
          aria-live="assertive"
        >
          <div className="max-w-md w-full glass rounded-3xl p-8 text-center">
            <div className="w-16 h-16 rounded-2xl bg-red-500/10 flex items-center justify-center mx-auto mb-6">
              <AlertTriangle className="w-8 h-8 text-red-400" aria-hidden="true" />
            </div>

            <h2 className="text-xl font-semibold text-white mb-2">
              Something went wrong
            </h2>

            <p className="text-slate-400 mb-6">
              We encountered an unexpected error. Please try again or return to the home page.
            </p>

            {/* Show error details in development */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mb-6 text-left">
                <summary className="text-slate-500 text-sm cursor-pointer hover:text-slate-400 transition-colors">
                  Error details
                </summary>
                <pre className="mt-2 p-4 bg-slate-800/50 rounded-xl text-xs text-red-400 overflow-auto max-h-40">
                  {this.state.error.toString()}
                  {this.state.errorInfo?.componentStack}
                </pre>
              </details>
            )}

            <div className="flex flex-col sm:flex-row gap-3">
              <button
                onClick={this.handleRetry}
                className="flex-1 py-3 px-4 bg-medical-500 hover:bg-medical-400 text-white rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-medical-300"
                aria-label="Try again"
              >
                <RefreshCw className="w-4 h-4" aria-hidden="true" />
                Try Again
              </button>

              <button
                onClick={this.handleGoHome}
                className="flex-1 py-3 px-4 bg-slate-700 hover:bg-slate-600 text-white rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-slate-500"
                aria-label="Go to home page"
              >
                <Home className="w-4 h-4" aria-hidden="true" />
                Go Home
              </button>
            </div>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

/**
 * RouteErrorBoundary - A simpler error boundary for route-level errors
 * Shows a full-page error state with navigation options
 */
class RouteErrorBoundary extends ErrorBoundary {
  render() {
    if (this.state.hasError) {
      return (
        <div
          className="min-h-screen animated-gradient grid-bg flex items-center justify-center p-8"
          role="alert"
          aria-live="assertive"
        >
          <div className="max-w-lg w-full glass rounded-3xl p-8 text-center">
            <div className="w-20 h-20 rounded-2xl bg-red-500/10 flex items-center justify-center mx-auto mb-6">
              <AlertTriangle className="w-10 h-10 text-red-400" aria-hidden="true" />
            </div>

            <h1 className="text-2xl font-bold text-white mb-3">
              Oops! Something went wrong
            </h1>

            <p className="text-slate-400 mb-8 leading-relaxed">
              We&apos;re sorry, but this page encountered an error.
              Our team has been notified and is working on a fix.
            </p>

            {/* Show error in development */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <div className="mb-6 p-4 bg-slate-800/50 rounded-xl text-left">
                <p className="text-red-400 text-sm font-mono break-all">
                  {this.state.error.toString()}
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-4">
              <button
                onClick={this.handleReload}
                className="flex-1 py-4 px-6 bg-gradient-to-r from-medical-500 to-medical-600 hover:from-medical-400 hover:to-medical-500 text-white font-semibold rounded-xl shadow-lg shadow-medical-500/25 transition-all flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-medical-300"
                aria-label="Reload this page"
              >
                <RefreshCw className="w-5 h-5" aria-hidden="true" />
                Reload Page
              </button>

              <button
                onClick={this.handleGoHome}
                className="flex-1 py-4 px-6 bg-slate-700 hover:bg-slate-600 text-white font-semibold rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-slate-500"
                aria-label="Return to home page"
              >
                <Home className="w-5 h-5" aria-hidden="true" />
                Back to Home
              </button>
            </div>

            <p className="mt-6 text-slate-500 text-sm">
              If this problem persists, please contact support.
            </p>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

/**
 * withErrorBoundary - HOC to wrap a component with an ErrorBoundary
 * 
 * @param {React.Component} Component - Component to wrap
 * @param {Object} props - Props to pass to ErrorBoundary
 * @returns {React.Component} Wrapped component
 * 
 * @example
 * const SafeComponent = withErrorBoundary(MyComponent)
 */
function withErrorBoundary(Component, errorBoundaryProps = {}) {
  return function WrappedComponent(props) {
    return (
      <ErrorBoundary {...errorBoundaryProps}>
        <Component {...props} />
      </ErrorBoundary>
    )
  }
}

export { ErrorBoundary, RouteErrorBoundary, withErrorBoundary }
export default ErrorBoundary

import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Search, X, ArrowRight, Loader2 } from 'lucide-react'
import toast from 'react-hot-toast'
import { searchDrugs, checkInteraction, getAlternatives, getMLPrediction } from '../services/api'
import { useDebouncedSearch } from '../hooks'

/**
 * DrugSearchInput - Reusable drug search input with autocomplete
 */
function DrugSearchInput({ 
  label, 
  placeholder,
  searchState,
  onSelect,
  inputId,
}) {
  const { 
    query, 
    setQuery, 
    results, 
    isLoading, 
    showResults, 
    setShowResults, 
    clear 
  } = searchState

  return (
    <div className="relative">
      <label 
        htmlFor={inputId}
        className="block text-sm font-medium text-slate-400 mb-2"
      >
        {label}
      </label>
      <div className="relative">
        <Search 
          className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" 
          aria-hidden="true"
        />
        <input
          id={inputId}
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => query.length >= 2 && setShowResults(true)}
          onBlur={() => setTimeout(() => setShowResults(false), 200)}
          placeholder={placeholder}
          className="w-full pl-12 pr-12 py-4 bg-slate-800/50 border border-slate-700/50 rounded-xl text-white placeholder-slate-500 focus:border-medical-500/50 focus:outline-none focus:ring-2 focus:ring-medical-500/20 transition-colors"
          autoComplete="off"
          aria-autocomplete="list"
          aria-controls={`${inputId}-suggestions`}
          aria-expanded={showResults && results.length > 0}
        />
        {query && (
          <button
            type="button"
            onClick={clear}
            className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
            aria-label={`Clear ${label.toLowerCase()}`}
          >
            {isLoading ? (
              <Loader2 className="w-5 h-5 animate-spin" aria-hidden="true" />
            ) : (
              <X className="w-5 h-5" aria-hidden="true" />
            )}
          </button>
        )}
      </div>

      {/* Suggestions dropdown */}
      <AnimatePresence>
        {showResults && results.length > 0 && (
          <motion.ul
            id={`${inputId}-suggestions`}
            role="listbox"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="absolute z-50 w-full mt-2 bg-slate-800 border border-slate-700 rounded-xl overflow-hidden shadow-2xl max-h-80 overflow-y-auto"
          >
            {results.map((drug, index) => (
              <li key={drug.id || index} role="option">
                <button
                  type="button"
                  onClick={() => onSelect(drug)}
                  className="w-full px-4 py-3 text-left hover:bg-medical-500/10 transition-colors border-b border-slate-700/50 last:border-b-0 focus:bg-medical-500/10 focus:outline-none"
                >
                  <p className="text-white font-medium">{drug.name}</p>
                  {drug.generic_name && (
                    <p className="text-slate-400 text-sm">{drug.generic_name}</p>
                  )}
                </button>
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  )
}

/**
 * InteractionChecker - Main component for checking drug interactions
 */
function InteractionChecker({ setResults, setAlternatives, setIsLoading, setMlPrediction, setMlLoading }) {
  // Use the custom hook for both drug searches
  const drug1Search = useDebouncedSearch(searchDrugs, { delay: 300, minLength: 2 })
  const drug2Search = useDebouncedSearch(searchDrugs, { delay: 300, minLength: 2 })

  // Handle drug selection
  const handleSelectDrug1 = useCallback((drug) => {
    drug1Search.selectItem(drug)
  }, [drug1Search])

  const handleSelectDrug2 = useCallback((drug) => {
    drug2Search.selectItem(drug)
  }, [drug2Search])

  // Swap drugs
  const handleSwap = useCallback(() => {
    const temp = drug1Search.query
    drug1Search.setQuery(drug2Search.query)
    drug2Search.setQuery(temp)
  }, [drug1Search, drug2Search])

  // Keyboard shortcut: Ctrl+Enter to check interaction
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        if (drug1Search.query.trim() && drug2Search.query.trim()) {
          document.getElementById('check-interaction-btn')?.click()
        }
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [drug1Search.query, drug2Search.query])

  const handleSubmit = async (e) => {
    e.preventDefault()

    const drug1 = drug1Search.query.trim()
    const drug2 = drug2Search.query.trim()

    if (!drug1 || !drug2) {
      toast.error('Please enter both drug names')
      return
    }

    if (drug1.toLowerCase() === drug2.toLowerCase()) {
      toast.error('Please enter two different drugs')
      return
    }

    setIsLoading(true)
    setResults(null)
    setAlternatives(null)
    if (setMlPrediction) setMlPrediction(null)

    try {
      // Check interaction
      const interactionResult = await checkInteraction(drug1, drug2)
      setResults(interactionResult)

      // Fetch ML prediction in parallel (if available)
      if (setMlPrediction && setMlLoading) {
        setMlLoading(true)
        getMLPrediction(drug1, drug2)
          .then(mlResult => {
            if (!mlResult.error) {
              setMlPrediction(mlResult)
            }
          })
          .catch(err => {
            console.log('ML prediction not available:', err.message)
          })
          .finally(() => {
            setMlLoading(false)
          })
      }

      // If there's an interaction, fetch alternatives
      if (interactionResult.has_interaction && interactionResult.interaction?.severity !== 'minor') {
        try {
          const alternativesResult = await getAlternatives(drug1, drug2)
          setAlternatives(alternativesResult)
        } catch (altError) {
          console.error('Could not fetch alternatives:', altError)
        }
      }

      // Show appropriate toast based on severity
      showInteractionToast(interactionResult)
    } catch (error) {
      console.error('Error checking interaction:', error)
      toast.error('Error checking interaction. Please try again.')
    } finally {
      setIsLoading(false)
    }
  }

  // Quick example buttons
  const quickExamples = [
    { drug1: 'Aspirin', drug2: 'Warfarin', severity: 'major', color: 'text-orange-400 bg-orange-500/10 border-orange-500/30' },
    { drug1: 'Simvastatin', drug2: 'Clarithromycin', severity: 'major', color: 'text-orange-400 bg-orange-500/10 border-orange-500/30' },
    { drug1: 'Metformin', drug2: 'Lisinopril', severity: 'safe', color: 'text-medical-400 bg-medical-500/10 border-medical-500/30' },
  ]

  const handleExampleClick = useCallback((example) => {
    drug1Search.setQuery(example.drug1)
    drug2Search.setQuery(example.drug2)
  }, [drug1Search, drug2Search])

  return (
    <div className="glass rounded-3xl p-8 max-w-2xl mx-auto">
      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Drug 1 Input */}
        <DrugSearchInput
          label="First Drug"
          placeholder="Enter first drug name (e.g., Aspirin)"
          searchState={drug1Search}
          onSelect={handleSelectDrug1}
          inputId="drug1-input"
        />

        {/* Swap button between inputs */}
        <div className="flex justify-center">
          <motion.button
            type="button"
            onClick={handleSwap}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            className="w-12 h-12 rounded-full bg-slate-800/50 hover:bg-medical-500/20 border border-slate-700/50 hover:border-medical-500/50 flex items-center justify-center transition-colors swap-rotate group"
            aria-label="Swap drug names"
          >
            <ArrowRight 
              className="w-5 h-5 text-slate-400 group-hover:text-medical-400 rotate-90 transition-colors" 
              aria-hidden="true"
            />
          </motion.button>
        </div>

        {/* Drug 2 Input */}
        <DrugSearchInput
          label="Second Drug"
          placeholder="Enter second drug name (e.g., Warfarin)"
          searchState={drug2Search}
          onSelect={handleSelectDrug2}
          inputId="drug2-input"
        />

        {/* Submit button */}
        <motion.button
          id="check-interaction-btn"
          type="submit"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          className="w-full py-4 bg-gradient-to-r from-medical-500 to-medical-600 hover:from-medical-400 hover:to-medical-500 text-white font-semibold rounded-xl shadow-lg shadow-medical-500/25 transition-all btn-hover relative group"
        >
          <span>Check Interaction</span>
          <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs text-white/50 hidden md:inline group-hover:text-white/70 transition-colors">
            Ctrl + Enter
          </span>
        </motion.button>
      </form>

      {/* Quick examples */}
      <div className="mt-6 pt-6 border-t border-slate-700/50">
        <p className="text-sm text-slate-500 mb-3">Quick examples:</p>
        <div className="flex flex-wrap gap-2" role="group" aria-label="Quick example drug pairs">
          {quickExamples.map((example, index) => (
            <motion.button
              key={index}
              onClick={() => handleExampleClick(example)}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              className="px-3 py-2 text-xs bg-slate-800/50 hover:bg-slate-700/50 text-slate-300 rounded-xl transition-colors flex items-center gap-2 border border-slate-700/50 hover:border-slate-600/50"
              aria-label={`Try ${example.drug1} and ${example.drug2} - ${example.severity} interaction`}
            >
              <span>{example.drug1} + {example.drug2}</span>
              <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-medium uppercase border ${example.color}`}>
                {example.severity}
              </span>
            </motion.button>
          ))}
        </div>
      </div>
    </div>
  )
}

/**
 * Show toast notification based on interaction severity
 */
function showInteractionToast(result) {
  if (!result.has_interaction) {
    toast.success('No known interaction found!')
    return
  }

  const severity = result.interaction?.severity
  switch (severity) {
    case 'minor':
      toast('Minor interaction detected', { icon: 'Ôä╣´©Å' })
      break
    case 'moderate':
      toast('Moderate interaction detected', { icon: 'ÔÜá´©Å' })
      break
    case 'major':
      toast.error('Major interaction detected!')
      break
    case 'contraindicated':
      toast.error('CONTRAINDICATED - Do not use together!')
      break
    default:
      toast('Interaction detected')
  }
}

